std::vector<Node> result;
if (start_idx < 0 || start_idx >= static_cast<int>(graph.nodes.size()) ||
    end_idx   < 0 || end_idx   >= static_cast<int>(graph.nodes.size())) {
    return result;
}

auto heuristic = [&](int a, int b) -> double {
    const Node& na = graph.nodes[a];
    const Node& nb = graph.nodes[b];
    // If nodes have x and y members, use Euclidean distance; otherwise fallback to 0.
    if constexpr (requires { na.x; na.y; nb.x; nb.y; }) {
        double dx = na.x - nb.x;
        double dy = na.y - nb.y;
        return std::sqrt(dx * dx + dy * dy);
    } else {
        return 0.0;
    }
};

const double INF = std::numeric_limits<double>::infinity();
std::vector<double> gScore(graph.nodes.size(), INF);
std::vector<int>    cameFrom(graph.nodes.size(), -1);
std::vector<bool>   closed(graph.nodes.size(), false);

using PQElement = std::pair<double, int>; // (fScore, node index)
auto cmp = [](const PQElement& lhs, const PQElement& rhs) { return lhs.first > rhs.first; };
std::priority_queue<PQElement, std::vector<PQElement>, decltype(cmp)> openSet(cmp);

gScore[start_idx] = 0.0;
openSet.emplace(heuristic(start_idx, end_idx), start_idx);

while (!openSet.empty()) {
    int current = openSet.top().second;
    openSet.pop();

    if (closed[current])
        continue;
    closed[current] = true;

    if (current == end_idx) {
        // Reconstruct path
        int idx = end_idx;
        while (idx != -1) {
            result.push_back(graph.nodes[idx]);
            idx = cameFrom[idx];
        }
        std::reverse(result.begin(), result.end());
        return result;
    }

    // Assume graph.adj is a vector of vectors of (neighbor, weight) pairs
    for (const auto& edge : graph.adj[current]) {
        int neighbor = edge.first;
        double weight = edge.second;

        if (closed[neighbor])
            continue;

        double tentative_g = gScore[current] + weight;
        if (tentative_g < gScore[neighbor]) {
            cameFrom[neighbor] = current;
            gScore[neighbor] = tentative_g;
            double fScore = tentative_g + heuristic(neighbor, end_idx);
            openSet.emplace(fScore, neighbor);
        }
    }
}

// No path found
return result;

